#include "MMDMotionPose.h"
#include "MMDMotionLegs.h"
#include <fstream>
#include <iostream>
#include <iomanip>
#include <random>
using namespace libmmd::sizing;
using namespace libmmd::sizing::detail;
libmmd::VMDMotion Key(const std::string& name,uint32_t f,const Vector& t=Vector::Zero()){libmmd::VMDMotion k;std::u16string u;libmmd::ConvU8ToU16(name,u);k.m_boneName.Set(libmmd::ConvertU16ToSjisString(u).c_str());k.m_frame=f;k.m_translate=t.cast<float>();for(int i=0;i<64;++i)k.m_interpolation[i]=i%16<8?20:107;return k;}
libmmd::PMXFile Model(){libmmd::PMXFile model;
auto bone=[&](std::string name,int parent,Eigen::Vector3f pos,uint16_t flags){libmmd::PMXBone b{};b.m_name=name;b.m_parentBoneIndex=parent;b.m_position=pos;b.m_boneFlag=static_cast<libmmd::PMXBoneFlags>(flags);model.m_bones.push_back(b);return int(model.m_bones.size())-1;};bone("センター",-1,Eigen::Vector3f::Zero(),6);
for(std::string side:{"左","右"}){float x=side=="左"?.8f:-.8f;int h=bone(side+"足",0,{x,8,0},2),k=bone(side+"ひざ",h,{x,4,-.3f},2),a=bone(side+"足首",k,{x,0,0},2),g=bone(side+"足ＩＫ",0,{x,0,0},0x26);auto& goal=model.m_bones[g];goal.m_ikTargetBoneIndex=a;goal.m_ikIterationCount=64;goal.m_ikLimit=.3f;for(int link:{k,h}){libmmd::PMXIKLink l{};l.m_ikBoneIndex=link;goal.m_ikLinks.push_back(l);}for(bool hip:{false,true}){libmmd::PMXRigidbody b{};b.m_name=side+(hip?"足":"ひざ");b.m_boneIndex=hip?h:k;b.m_shape=hip?libmmd::PMXRigidbody::Shape::Sphere:libmmd::PMXRigidbody::Shape::Capsule;b.m_shapeSize=hip?Eigen::Vector3f(1.4f,0,0):Eigen::Vector3f(.35f,3.2f,0);b.m_translate=hip?Eigen::Vector3f(x,8,0):Eigen::Vector3f(x,2,0);b.m_rotate.setZero();b.m_op=libmmd::PMXRigidbody::Operation::Static;model.m_rigidbodies.push_back(b);}}
return model;}

int main(){try{auto model=Model();for(auto& b:model.m_bones)b.m_position*=.1f;for(auto& b:model.m_rigidbodies){b.m_shapeSize*=.1f;b.m_translate*=.1f;}Rig rig(model);const auto pairs=LegCollisionPairs(rig);std::vector<int> controls{rig.Find("左足ＩＫ"),rig.Find("右足ＩＫ")};double length=0;for(std::string side:{"左","右"}){int h=rig.Find(side+"足"),k=rig.Find(side+"ひざ"),a=rig.Find(side+"足首");length+=(model.m_bones[h].m_position-model.m_bones[k].m_position).norm()+(model.m_bones[k].m_position-model.m_bones[a].m_position).norm();}const double budget=.04*length,step=.25*budget;Options options;options.tolerance=.1;int failures=0;std::cout<<std::setprecision(14);
for(bool switching:{false,true}){libmmd::VMDFile clip;clip.m_motions.push_back(Key("センター",0));const Vector start[2]={{-.65,1,0},{.65,1,0}},end[2]={{-1.4054584358375,4.4902893386136,.18369513659895},{1.310143212459,4.9359652953181,1.7918076183566}};for(int f=0;f<18;++f)for(int i=0;i<2;++i){const double blend=std::clamp((f-5)/6.,0.,1.);clip.m_motions.push_back(Key(i?"右足ＩＫ":"左足ＩＫ",f,.1*((1.-blend)*start[i]+blend*end[i])));}if(switching)for(auto frame:{11u,13u}){libmmd::VMDIk key(frame,1);libmmd::VMDIkInfo info;std::u16string name;libmmd::ConvU8ToU16("左足ＩＫ",name);info.m_name.Set(libmmd::ConvertU16ToSjisString(name).c_str());info.m_enable=frame==13;key.m_ikInfos.push_back(info);clip.m_iks.push_back(key);}Motion input(clip);auto adjusted=clip;Analysis analysis;ApplyLegAvoidance(rig,adjusted,options,analysis,nullptr,{});Motion output(adjusted);Vector previous[2]={Vector::Zero(),Vector::Zero()};double peakCorrection=0;for(int f=0;f<18;++f){Pose a(rig,input,f),b(rig,output,f);const auto before=LegPenetrations(a,pairs,options.collisionMargin),after=LegPenetrations(b,pairs,options.collisionMargin);for(size_t i=0;i<before.size();++i)if(after[i]>std::max(before[i],options.tolerance)+1e-6)++failures;if(*std::max_element(after.begin(),after.end())>*std::max_element(before.begin(),before.end())+2e-6)++failures;for(int i=0;i<2;++i){const int c=controls[i],ankle=model.m_bones[c].m_ikTargetBoneIndex;Vector correction=b.positions[c]-a.positions[c];peakCorrection=std::max(peakCorrection,correction.norm());const double delta=(correction-previous[i]).norm();const double errorBefore=(a.positions[ankle]-a.positions[c]).norm(),errorAfter=(b.positions[ankle]-b.positions[c]).norm();if(errorAfter>errorBefore+options.tolerance+1e-6||std::abs(correction.y())>1e-6||correction.norm()>budget+1e-6)++failures;if(!a.ikEnabled[c]){if(correction.norm()>1e-6)++failures;}else if(f>0&&delta>step+1e-6){++failures;std::cout<<"STEP_FAIL switching="<<switching<<" frame="<<f<<" foot="<<i<<" actual="<<delta<<" limit="<<step<<"\n";}if(f>=10&&f<=14)std::cout<<"sample "<<switching<<" "<<f<<" "<<i<<" correction="<<correction.norm()<<" step="<<delta<<"\n";previous[i]=correction;}}
if(peakCorrection<step*1.5)++failures;std::cout<<"peak_correction="<<peakCorrection<<"\n";}
std::cout<<"regression_failures="<<failures<<"\n";return failures?1:0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 2;}}
